compare_tag : begin

        /*cache hit (tag match and cache entry is valid)*/

    if (cpu_req.addr[TAGMSB:TAGLSB] == tag_read.tag && tag_read.valid) begin

        v_cpu_res.ready = '1;

    /*write hit*/

    if (cpu_req.rw) begin

        /*read/modify cache line*/

        tag_req.we = '1; data_req.we = '1;

        /*no change in tag*/

        tag_write.tag = tag_read.tag;

        tag_write.valid = '1;

        /*cache line is dirty*/

        tag_write.dirty = '1;

    end

    /*xaction is finished*/

    vstate = idle;

end

/*cache miss*/

else begin

    /*generate new tag*/

    tag_req.we = '1;

    tag_write.valid = '1;

